-- Thread 1 (sort 297): honor-of-parents-fifth-commandment-the-corban-tradition-voids-in-sirach-and-tobit
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'honor-of-parents-fifth-commandment-the-corban-tradition-voids-in-sirach-and-tobit',
       'The honor of parents — the fifth-commandment substance the Pharisaic Corban-tradition voids — Sirach (Ecclesiasticus) 3 and 7, and Tobit 4',
       'Matt 15:3-6''s Pharisaic-Corban-tradition exposé — *Why do ye also transgress the commandment of Elohim (God) by your tradition? For Elohim (God) commanded, saying, Honour thy father and mother ... But ye say, Whosoever shall say to his father or his mother, It is a gift, by whatsoever thou mightest be profited by me; And honour not his father or his mother, he shall be free. Thus have ye made the commandment of Elohim (God) of none effect by your tradition* — read against the wisdom-stream''s direct articulation of the fifth-commandment substance the Pharisaic-Corban-tradition voids. Five moves: Sirach (Ecclesiasticus) 3:1 names *hear me your father, O children, and do thereafter, that you may be safe* (the wisdom-stream''s headline articulation of the parental-honor architecture as the foundation-of-the-children''s-safety); Sirach 3:8 names the holistic-honor — *honour your father and mother both in word and deed, that a blessing may come upon you from them* (the architecture the Pharisaic-Corban-tradition split, allowing word-without-deed); Sirach 7:27 names the whole-heart-honor — *honour your father with your whole heart, and forget not the sorrows of your mother* (the heart-level architecture the King will close the loop on at vv.18-20); Sirach 3:16 names the worst-end — *he that forsaketh his father is as a blasphemer; and he that angereth his mother is cursed: of Yahuah (God)* (the disposition of the Pharisaic-Corban-tradition at its most-honest naming — blasphemy and curse); Tobit 4:3 names the deathbed-instruction — *my son, when I am dead, bury me; and despise not your mother, but honour her all the days of your life* (the second-Temple Yashar''el (Israel)-household''s articulation of the all-the-days-of-her-life parental-honor extension). The framework reads the cluster as the wisdom-stream''s direct corroboration of the Torah-substance the King defends against the Pharisaic-Corban-tradition. The Pharisaic-system had built the Corban-vow-mechanism to override the parental-honor commandment while preserving its righteousness-credentialing; the wisdom-stream had named the substance the tradition was voiding centuries before. The King''s-charge at vv.3-6 lands at the same load-bearing diagnostic the wisdom-stream had named: the disposition that voids the parental-honor commandment is at the architecture of blasphemy-against-the-Torah-the-Father-spoke-from-Sinai.',
       sv.verse_id, ev.verse_id, 'complete_study', 297
  FROM _s145_verse_lookup sv, _s145_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 15 AND sv.verse_number = 4
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 15 AND ev.verse_number = 6
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 298): the-heart-the-source-of-evil-not-the-father-in-sirach-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-heart-the-source-of-evil-not-the-father-in-sirach-and-wisdom-of-solomon',
       'The heart the source of evil — not the Father — Sirach (Ecclesiasticus) 15 and 27, and Wisdom of Solomon 1',
       'Matt 15:10-20''s heart-defilement-versus-mouth-defilement teaching — *not that which goeth into the mouth defileth a man; but that which cometh out of the mouth, this defileth a man ... those things which proceed out of the mouth come forth from the heart; and they defile the man. For out of the heart proceed evil thoughts, murders, adulteries, fornications, thefts, false witness, blasphemies* — read against the wisdom-stream''s direct articulation of the heart-as-the-source-of-evil-and-the-Father-NOT-being-the-source substance. Four moves: Sirach (Ecclesiasticus) 15:11 names the Father-NOT-the-source — *say not you, It is through Yahuah (God) that I fell away: for you oughtest not to do the things that he hates*; Sirach 15:20 names the corollary — *he has commanded no man to do wickedly, neither has he given any man licence to sin* (the substance the King''s-articulation at Matt 15:18-19 lands the operative-form for); Sirach 27:6 names the tree-and-fruit-and-utterance architecture — *the fruit declareth if the tree have been dressed; so is the utterance of a conceit in the heart of man* (the heart''s-substance manifests in the mouth''s-utterance, the same architecture the King''s Matt 7:17-20 and Matt 15:18 walk); Wisdom of Solomon 1:11 names the mouth-substance overlap with the King''s-Matt-15:19-catalogue — *beware of murmuring, which is unprofitable; and refrain your tongue from backbiting ... the mouth that belieth slayeth the soul.* The framework reads the cluster as the wisdom-stream''s direct corroboration of the heart-and-mouth-substance-as-the-locus-of-defilement architecture the King restores at vv.10-20. The Torah''s clean-and-unclean architecture of Vayikra (Leviticus) 11 is NOT abolished (Acts 10:14''s direct evidence — Kefa (Peter) had never eaten anything common or unclean post-resurrection); the rabbinic-fence-tradition that had located-defilement at the un-washed-hands-and-the-food-categorically-touched-by-them IS dismantled; the heart-Torah of Yirmeyahu (Jeremiah) 31:33 / Yechezk''el (Ezekiel) 36:26-27 is restored. The wisdom-stream had named the architecture; the King names the operative-form at the gospel-precision.',
       sv.verse_id, ev.verse_id, 'complete_study', 298
  FROM _s145_verse_lookup sv, _s145_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 15 AND sv.verse_number = 10
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 15 AND ev.verse_number = 20
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 299): gathering-of-the-scattered-twelve-tribes-in-sirach-and-2-esdras-and-tobit
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'gathering-of-the-scattered-twelve-tribes-in-sirach-and-2-esdras-and-tobit',
       'The gathering of the scattered twelve tribes — Sirach (Ecclesiasticus) 36, 2 Esdras (4 Ezra) 13, and Tobit 13 (FRAMEWORK-MAJOR)',
       'Matt 15:24''s *I am not sent but unto the lost sheep of the house of Yashar''el (Israel)* — the King''s-own-mission-scope statement, paired with the Matt 10:5-6''s apostolic-mission-scope, reading as the load-bearing scripture-anchor for the framework''s gathering-of-the-scattered-twelve-tribes thesis — read against the wisdom-stream''s direct articulation of the gathering-of-the-scattered-tribes prayer-and-prophecy substance. Five moves: Sirach (Ecclesiasticus) 36:1 names the petition — *have mercy upon us, O Yahuah (God) of all, and behold us* (the wisdom-stream''s-prayer-for-the-gathering); Sirach 36:11 names THE direct verbal-anchor — *gather all the tribes of Jacob together, and inherit you them, as from the beginning* (the explicit wisdom-stream-articulation of the twelve-tribes-restoration the prophets had named at Yechezk''el (Ezekiel) 37:21; Yirmeyahu (Jeremiah) 31:8-10; Hosea 1:10-11; Zekharyah (Zechariah) 10:6-10); 2 Esdras (4 Ezra) 13:40 names the ten-tribes-carried-away — *those are the ten tribes, which were carried away prisoners out of their own land in the time of Osea the king, whom Salmanasar the king of Assyria led away captive* (the wisdom-stream''s-direct-articulation of the Assyrian-exile-architecture the lost-sheep-mission-scope addresses); 2 Esdras 13:48 names the remnant-within-the-borders — *but those that be left behind of your people are they that are found within my borders* (the wisdom-stream''s naming of both registers the King''s-mission addresses); Tobit 13:5 names the scourge-then-mercy-then-gathering-out-of-all-nations — *he will scourge us for our iniquities, and will have mercy again, and will gather us out of all nations, among whom he has scattered us* (the operative-architecture the King''s-mission enacts). The framework reads the cluster as FRAMEWORK-MAJOR for the lost-sheep-mission-scope''s wisdom-stream corroboration. The Pharisaic-system had built credentialing-systems on top of the binary (Yahudah (Judah) and the nations, no scattered-twelve-tribes coming-home); the wisdom-stream had preserved the architecture the prophets had named. The King''s-mission at v.24 IS the operative-form of the wisdom-stream''s-prayer at Sirach 36:11; the lost-sheep-of-the-house-of-Yashar''el (Israel) the King is sent-to IS the all-the-tribes-of-Ya''aqov (Jacob) the wisdom-stream had prayed for the gathering of. The framework reads the Canaanite-woman''s mercy-at-the-crumbs-substance (vv.25-28) within the architecture — as the master''s-table-mercy-to-the-categorical-nations-individual that does NOT collapse the seed-distinction (Red Line #7) but operates within it.',
       sv.verse_id, ev.verse_id, 'complete_study', 299
  FROM _s145_verse_lookup sv, _s145_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 15 AND sv.verse_number = 24
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 15 AND ev.verse_number = 24
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 300): seed-of-promise-specifically-to-yasharel-not-other-seed-of-avraham-in-jubilees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'seed-of-promise-specifically-to-yasharel-not-other-seed-of-avraham-in-jubilees',
       'The seed of promise specifically to Yashar''el (Israel) — not to the other seed of Avraham (Abraham) — Jubilees 15 and 16 (FRAMEWORK-MAJOR)',
       'Matt 15:22-28''s Canaanite-woman pericope — the King''s-children-vs-dogs distinction at v.26 (*it is not meet to take the children''s bread, and to cast it to dogs*) and the woman''s-acceptance-of-the-architecture at v.27 (*Truth, Lord: yet the dogs eat of the crumbs which fall from their masters'' table*) — read against the wisdom-stream''s direct articulation of the seed-of-promise-specifically-to-Yashar''el (Israel)-NOT-to-other-seed-of-Avraham (Abraham) substance. Four moves: Jubilees 15:30 names THE direct verbal-anchor — *for Ishmael and his sons and his brothers and Esau, Yahuah (God) did not cause to approach Him, and he chose them not because they are the children of Abraham, because He knew them, but He chose Yashar''el (Israel) to be His people* (the wisdom-stream''s precise articulation of the seed-distinction the Pharisaic-system''s-binary erased and the modern-Hebrew-Roots-false-inclusion-gospel''s seed-collapse erases); Jubilees 15:31 names the spiritual-jurisdictional architecture — *for there are many nations and many peoples, and all are His, and over all has He placed spirits in authority to lead them astray from Him* (the *bene Elohim* allocation per Devarim (Deuteronomy) 32:8-9''s Septuagint and Dead Sea Scrolls reading); Jubilees 15:32 names the Yashar''el (Israel)-under-direct-rule architecture — *but over Yashar''el (Israel) He did not appoint any angel or spirit, for He alone is their ruler* (the architecture the King''s-mission-to-the-lost-sheep at v.24 enacts under the Father''s-direct-shepherding); Jubilees 16:17 names the holy-seed-from-the-sons-of-Yitschaq (Isaac) — *and (that) all the seed of his sons should be nations, and be reckoned with the nations; but from the sons of Isaac one should become a holy seed, and should not be reckoned among the nations. For he should become the portion of Yahuah (God) most High* (the explicit wisdom-stream-articulation of the holy-seed-from-Yitschaq (Isaac)-NOT-reckoned-among-the-nations architecture). The framework reads the cluster as FRAMEWORK-MAJOR for the Red Line #7 seed-distinction''s wisdom-stream corroboration. The wisdom-stream had named the architecture with explicit-precision centuries before the Pharisaic-binary and the modern-false-inclusion-gospel''s seed-collapse arose. The Canaanite-woman is outside the seed-architecture the wisdom-stream had named; the King''s-distinction at v.26 operates exactly in the architecture; the woman''s-acceptance-at-v.27 honors the architecture; the King''s-mercy-at-the-crumbs-substance at v.28 grants-within-the-architecture without collapsing it. The framework reads this in continuity with Romans 9:6-13''s *they are not all Yashar''el (Israel), which are of Yashar''el (Israel) ... in Yitschaq (Isaac) shall thy seed be called* — Paul''s articulation of the same wisdom-stream substance the inherited-Christian reading flattens-to-the-replacement-theology-of-the-church-replacing-Yashar''el (Israel) or the Hebrew-Roots-false-inclusion-gospel''s self-selection-by-belief-and-practice.',
       sv.verse_id, ev.verse_id, 'complete_study', 300
  FROM _s145_verse_lookup sv, _s145_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 15 AND sv.verse_number = 22
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 15 AND ev.verse_number = 28
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 301): yovel-cycle-and-the-year-weeks-architecture-in-jubilees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'yovel-cycle-and-the-year-weeks-architecture-in-jubilees',
       'The Yovel cycle and the year-weeks architecture — Jubilees 50',
       'Matt 15:32-39''s feeding-of-the-four-thousand with seven-loaves-and-seven-baskets-remaining — paired with the twelve-baskets-of-the-feeding-of-the-five-thousand at Matt 14:20 — read against the wisdom-stream''s direct articulation of the Yovel-cycle and year-weeks architecture Jubilees structures the entire-Tanakh-chronology around. Three moves: Jubilees 50:1 names the Sabbath-architecture-revealed-in-the-desert-of-Sinai (*after this law I made known to you the days of the Sabbaths in the desert of Sinai*); Jubilees 50:2 names the jubilee-years-in-the-sabbaths-of-years (*I told you of the Sabbaths of the land on Mount Sinai, and I told you of the jubilee years in the sabbaths of years* — the seven-times-seven-years-equals-forty-nine-then-the-fiftieth-year-jubilee substance of Vayikra (Leviticus) 25:8-10); Jubilees 50:4 names the forty-nine-jubilees-from-Adam-until-this-day chronological-architecture (*I have ordained for you the year-weeks and the years and the jubilees: there are forty-nine jubilees from the days of Adam until this day*). The framework reads the cluster as the wisdom-stream''s articulation of the Yovel-substance the seven-baskets-of-the-second-feeding signal at the chapter''s-closing-scene. The seven-architecture of the second-feeding signals the Yovel-completion-substance the Jubilees-wisdom-stream had structured the entire-Tanakh-chronology around. The King''s-pedagogical-double-feeding (twelve-baskets at Matt 14:20 for the twelve-tribes-gathering; seven-baskets at Matt 15:37 for the Yovel-completion) encodes the architecture''s-completion-arc the wisdom-stream had named the chronological-substance for. The framework reads this in continuity with Luke 4:18-21''s Natsareth (Nazareth)-synagogue-reading of Yeshayahu (Isaiah) 61:1-2''s *acceptable year of Yahuah (the LORD)* — the King''s-naming-himself as the One the Yovel-substance-proclaims at the gospel-fulfillment.',
       sv.verse_id, ev.verse_id, 'complete_study', 301
  FROM _s145_verse_lookup sv, _s145_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 15 AND sv.verse_number = 32
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 15 AND ev.verse_number = 39
ON CONFLICT (slug) DO NOTHING;

